def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def runs(row):
        result = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            result.append((start, c - 1, c - start))
        return result

    for r, row in enumerate(grid):
        rr = runs(row)
        if not rr:
            continue
        start, end, length = max(rr, key=lambda x: x[2])
        last = max(c for c, v in enumerate(row) if v != bg)
        if last == w - 1:
            continue

        # Short bars extend; longer left-edge bars usually form complete
        # marks, unless they have a separate colored endpoint after them.
        separate_endpoint = any(a > end for a, b, n in rr)
        extend = (3 <= length <= 7 or start > 0 or separate_endpoint)

        # A shorter bar directly above a longer bar with the same start
        # is part of the shape rather than an extending ray.
        if r + 1 < h:
            below = runs(grid[r + 1])
            if any(a == start and n > length for a, b, n in below):
                extend = False

        if extend:
            for c in range(last + 1, w):
                out[r][c] = 1

    return out
